Object.assign(SNIP,{"h07sinh": "// sinh.cpp: chạy \"sinh 17\" sẽ dùng hạt giống 17, mỗi hạt giống cho một test khác nhau\n#include <bits/stdc++.h>\nusing namespace std;\n\nint main(int argc, char* argv[]) {\n    mt19937 rng(atoi(argv[1]));\n    auto ngauNhien = [&](int lo, int hi) { return (int)(rng() % (hi - lo + 1)) + lo; };\n    ofstream f(\"DAYCON.INP\");\n    int n = ngauNhien(1, 8);\n    f << n << \"\\n\";\n    for (int i = 0; i < n; i++) f << ngauNhien(-10, 10) << \" \";\n    f << \"\\n\";\n    return 0;\n}", "h07bat": "@echo off\nfor /l %%i in (1,1,300) do (\n    sinh.exe %%i\n    DAYCON.exe\n    trau.exe\n    fc DAYCON.OUT TRAU.OUT > nul\n    if errorlevel 1 (\n        echo Lech o test %%i\n        type DAYCON.INP\n        pause\n        exit\n    )\n)\necho Khop ca 300 test\npause"});PRESET_NOTES["l7"]={"Ví dụ: Bộ sinh số ngẫu nhiên có hạt giống": "Cùng hạt giống thì cùng dãy test: chạy lại bao nhiêu lần cũng ra đúng ba test này. Trên máy thật dùng mt19937 với hạt giống lấy từ dòng lệnh.", "Ví dụ: Đối chiếu trâu và tối ưu": "Bài “đoạn con có tổng lớn nhất”. Ở lần 6, máy tìm được dãy −2 −1: lời giải tối ưu trả 0 vì khởi tạo best = 0, trong khi đoạn phải khác rỗng nên đáp án là −1.", "Ví dụ: Thu nhỏ test lệch": "Tăng dần n: test lệch thu gọn còn một phần tử âm. Nhìn là thấy lỗi: khởi tạo best bằng a[0] (hoặc −∞), không phải 0."};EX_HINTS["l7"]=[["Lời giải trâu: thử mọi đoạn [i, j], cộng dồn khi j tăng. Đối chiếu trên dãy nhỏ có số âm.", "Test lệch nhỏ nhất: một ngày lỗ, ví dụ n = 1, a = −7. Code mẫu in 0.", "Khởi tạo cur và best bằng a[0], rồi chạy từ ngày thứ hai."], ["Lời giải trâu: đếm từng phần tử ≤ x.", "Test lệch: x lớn hơn hoặc bằng mọi phần tử (đáp án n). Code mẫu trả n − 1.", "Khoảng tìm kiếm của “vị trí đầu tiên > x” là [0, n]: hi = n. Hoặc dùng upper_bound."], ["Lời giải trâu: hai vòng lặp i < j. Sinh test với giá trị trong {1, 2, 3} để có nhiều số trùng.", "Nhóm k số bằng nhau cho k(k − 1)/2 cặp, không phải k − 1.", "Số cặp tới khoảng 5·10⁹: long long."]];
