const PR7=[{label:"Ví dụ: Bộ sinh số ngẫu nhiên có hạt giống",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nlong long hat = 12345;                  // hạt giống cố định\n\nint ngauNhien(int lo, int hi) {\n    hat = (hat * 1103515245 + 12345) % 2147483648LL;\n    return lo + (int)(hat / 65536 % (hi - lo + 1));\n}\n\nint main() {\n    for (int t = 1; t <= 3; t++) {\n        int n = ngauNhien(1, 6);\n        cout << \"test \" << t << \": n = \" << n << \":\";\n        for (int i = 0; i < n; i++) cout << \" \" << ngauNhien(-5, 5);\n        cout << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"vars",names:["hat","t","n"]}]},{label:"Ví dụ: Đối chiếu trâu và tối ưu",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nlong long hat = 12345;                  // hạt giống cố định\n\nint ngauNhien(int lo, int hi) {\n    hat = (hat * 1103515245 + 12345) % 2147483648LL;\n    return lo + (int)(hat / 65536 % (hi - lo + 1));\n}\n\nlong long trau(const vector<long long>& a) {        // thử mọi đoạn: chắc chắn đúng\n    long long best = a[0];\n    for (int i = 0; i < (int)a.size(); i++) {\n        long long s = 0;\n        for (int j = i; j < (int)a.size(); j++) { s += a[j]; best = max(best, s); }\n    }\n    return best;\n}\n\nlong long totUu(const vector<long long>& a) {       // O(n), nhưng có lỗi ẩn\n    long long cur = 0, best = 0;\n    for (long long x : a) {\n        cur = max(x, cur + x);\n        best = max(best, cur);\n    }\n    return best;\n}\n\nint main() {\n    for (int lan = 1; lan <= 500; lan++) {\n        int n = ngauNhien(1, 4);\n        vector<long long> a(n);\n        for (auto& x : a) x = ngauNhien(-4, 4);\n        if (trau(a) != totUu(a)) {\n            cout << \"Lech o lan \" << lan << \":\";\n            for (long long x : a) cout << \" \" << x;\n            cout << \"\\ntrau = \" << trau(a) << \", tot uu = \" << totUu(a) << \"\\n\";\n            return 0;\n        }\n    }\n    cout << \"Khop ca 500 test\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["lan","n"]}]},{label:"Ví dụ: Thu nhỏ test lệch",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nlong long hat = 12345;                  // hạt giống cố định\n\nint ngauNhien(int lo, int hi) {\n    hat = (hat * 1103515245 + 12345) % 2147483648LL;\n    return lo + (int)(hat / 65536 % (hi - lo + 1));\n}\n\nlong long trau(const vector<long long>& a) {        // thử mọi đoạn: chắc chắn đúng\n    long long best = a[0];\n    for (int i = 0; i < (int)a.size(); i++) {\n        long long s = 0;\n        for (int j = i; j < (int)a.size(); j++) { s += a[j]; best = max(best, s); }\n    }\n    return best;\n}\n\nlong long totUu(const vector<long long>& a) {       // O(n), nhưng có lỗi ẩn\n    long long cur = 0, best = 0;\n    for (long long x : a) {\n        cur = max(x, cur + x);\n        best = max(best, cur);\n    }\n    return best;\n}\n\nint main() {\n    for (int n = 1; n <= 5; n++)            // thử n nhỏ trước: test lệch đầu tiên là nhỏ nhất\n        for (int lan = 0; lan < 100; lan++) {\n            vector<long long> a(n);\n            for (auto& x : a) x = ngauNhien(-3, 3);\n            if (trau(a) != totUu(a)) {\n                cout << \"n = \" << n << \":\";\n                for (long long x : a) cout << \" \" << x;\n                cout << \" -> trau \" << trau(a) << \", tot uu \" << totUu(a) << \"\\n\";\n                return 0;\n            }\n        }\n    cout << \"Khong tim thay\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["n","lan"]}]}];
