makeEx2(document.getElementById("ex-l7"),sim7,[{t:"Đoạn con lãi nhất",d:"File LAINHAT.INP: dòng 1 là n (1 ≤ n ≤ 10⁵); dòng 2 là n số nguyên (|aᵢ| ≤ 10⁹): lãi của n ngày liên tiếp (có thể âm). Ghi vào LAINHAT.OUT tổng lớn nhất của một đoạn ngày liên tiếp, ít nhất một ngày. Code mẫu đúng với ví dụ nhưng có lỗi.",tests:[{in:"7\n2 -5 3 -1 4 -2 1",out:"6"},{in:"3\n-3 -1 -4",out:"-1"},{in:"1\n5",out:"5"},{in:"5\n1000000000 1000000000 1000000000 1000000000 1000000000",out:"5000000000"},{in:"40\n0 -6 2 10 -9 -8 7 -7 1 8 -9 6 -4 -9 -8 3 3 -8 -3 -8 7 3 -9 8 -7 -3 10 10 8 -9 8 8 2 -9 -3 -9 7 -6 -1 3",out:"37"},{in:"1\n-7",out:"-7"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"LAINHAT.INP\", \"r\")) {\n        freopen(\"LAINHAT.INP\", \"r\", stdin);\n        freopen(\"LAINHAT.OUT\", \"w\", stdout);\n    }\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto& x : a) cin >> x;\n    long long cur = 0, best = 0;\n    for (long long x : a) {\n        cur = max(x, cur + x);\n        best = max(best, cur);\n    }\n    cout << best << \"\\n\";\n    return 0;\n}",file:"LAINHAT",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>((i*7919)%201)-100).join(" "),ns:[200,800,3200],need:"n",limit:n=>60*n+500,why:"Lời giải phải O(n): không thử mọi đoạn với n = 10⁵."}},{t:"Đếm số không vượt quá",d:"File KHONGVUOT.INP: dòng 1 là n, x (1 ≤ n ≤ 10⁵, |x| ≤ 10⁹); dòng 2 là n số nguyên đã sắp tăng dần. Ghi vào KHONGVUOT.OUT số phần tử ≤ x. Code mẫu dùng tìm kiếm nhị phân nhưng có lỗi lệch một.",tests:[{in:"5 3\n1 3 3 5 8",out:"3"},{in:"1 4\n5",out:"0"},{in:"1 5\n5",out:"1"},{in:"3 9\n2 2 2",out:"3"},{in:"4 100\n1 2 3 4",out:"4"},{in:"3 -6\n-5 0 5",out:"0"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"KHONGVUOT.INP\", \"r\")) {\n        freopen(\"KHONGVUOT.INP\", \"r\", stdin);\n        freopen(\"KHONGVUOT.OUT\", \"w\", stdout);\n    }\n    int n;\n    long long x;\n    cin >> n >> x;\n    vector<long long> a(n);\n    for (auto& v : a) cin >> v;\n    int lo = 0, hi = n - 1;                 // tìm vị trí đầu tiên có a[i] > x\n    while (lo < hi) {\n        int mid = (lo + hi) / 2;\n        if (a[mid] > x) hi = mid;\n        else lo = mid + 1;\n    }\n    cout << lo << \"\\n\";\n    return 0;\n}",file:"KHONGVUOT"},{t:"Cặp bằng nhau",d:"File CAPBANG.INP: dòng 1 là n (1 ≤ n ≤ 10⁵); dòng 2 là n số nguyên (|aᵢ| ≤ 10⁹). Ghi vào CAPBANG.OUT số cặp chỉ số i < j có aᵢ = aⱼ. Code mẫu sai khi có từ ba số bằng nhau trở lên.",tests:[{in:"3\n7 7 7",out:"3"},{in:"5\n1 2 1 2 1",out:"4"},{in:"1\n5",out:"0"},{in:"3\n1 2 3",out:"0"},{in:"10\n4 4 4 4 4 4 4 4 4 4",out:"45"},{in:"30\n1 3 1 3 2 3 3 1 1 3 3 3 1 2 1 3 3 1 3 1 3 1 2 3 3 2 2 2 3 2",out:"148"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"CAPBANG.INP\", \"r\")) {\n        freopen(\"CAPBANG.INP\", \"r\", stdin);\n        freopen(\"CAPBANG.OUT\", \"w\", stdout);\n    }\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto& x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long d = 0;\n    for (int i = 0; i + 1 < n; i++)\n        if (a[i] == a[i + 1]) d++;\n    cout << d << \"\\n\";\n    return 0;\n}",file:"CAPBANG",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>i%5).join(" "),ns:[200,800,3200],need:"nlogn",limit:n=>80*n*Math.log2(n)+500,why:"Hai vòng lặp i < j là O(n²); sắp xếp rồi đếm theo nhóm là O(n log n)."}}]);

